fn first_word(text: &str) -> &str {
    let bytes = text.as_bytes();
    let mut index: usize = 0;
    while index < bytes.len() {
        if bytes[index] == b' ' {
            return &text[0..index];
        }
        index += 1;
    }
    &text[..]
}

