fn print_all(tasks: &[Task]) {
    for (index, task) in tasks.iter().enumerate() {
        println!("{}. [{}] {}", index + 1, if task.done { "x" } else { " " }, task.title);
    }
}

fn main() {
    let mut tasks: Vec<Task> = Vec::new();
    add_task(&mut tasks, "Learn Rust");
    add_task(&mut tasks, "Write a program");
    print_all(&tasks);
}

